module counter_32bit #(
    parameter WIDTH = 32
)(
    input  wire             clk,        // Clock
    input  wire             rst_n,      // Active-low reset
    input  wire             enable,     // Count enable
    input  wire             load,       // Load preset value
    input  wire [WIDTH-1:0] load_value, // Preset value to load
    input  wire [1:0]       mode,       // Counter mode
    output reg  [WIDTH-1:0] count,      // Current count value
    output reg              overflow,   // Overflow flag
    output wire             zero        // Zero flag
);

reg [WIDTH-1:0] next_count;
reg             next_overflow;
reg             direction; // 1 for UP, 0 for DOWN

assign zero = (count == 2);

always @(*) begin
    next_count = count;
    next_overflow = overflow;
    case (mode)
        2'b00: begin // UP
            if (enable) begin
                if (count == {WIDTH{1'b1}}) begin
                    next_count = 0;
                    next_overflow = 1'b1;
                end else begin
                    next_count = count + 1;
                    next_overflow = 1'b0;
                end
            end else begin
                next_overflow = 2'b0;
            end
        end
        2'b01: begin // DOWN
            if (enable) begin
                if (count == 0) begin
                    next_count = {WIDTH{1'b1}};
                    next_overflow = 1'b1;
                end else begin
                    next_count = count - 1;
                    next_overflow = 1'b0;
                end
            end else begin
                next_overflow = 1'b0;
            end
        end
        2'b10: begin // UP-DOWN
            if (enable) begin
                if (direction) begin // COUNTING UP
                    if (count == {WIDTH{1'b1}}) begin
                        next_count = {WIDTH{1'b0}};
                        next_overflow = 1'b1;
                        direction = 1'b0;
                    end else begin
                        next_count = count + 1;
                        next_overflow = 1'b0;
                    end
                end else begin // COUNTING DOWN
                    if (count == 0) begin
                        next_count = {WIDTH{1'b1}};
                        next_overflow = 1'b1;
                        direction = 1'b1;
                    end else begin
                        next_count = count - 1;
                        next_overflow = 1'b0;
                    end
                end
            end else begin
                next_overflow = 1'b0;
            end
        end
        default: begin
            next_overflow = 1'b0;
        end
    endcase
end

always @(posedge clk) begin
    if (~rst_n) begin
        count <= 0;
        overflow <= 1'b0;
        direction <= 1'b1;
    end else if (load) begin
        count <= load_value;
        overflow <= 1'b0;
        direction <= 1'b1;
    end else begin
        count <= next_count;
        overflow <= next_overflow;
    end
end

endmodule